#!/usr/bin/env node
// bpmn: {"file":"pr-review.bpmn","elements":["StoreRef_Repo"]}
//
// Claude Code PreToolUse hook, generated by flowforge-generate from the live data store
// "Pull Requests im Repository" in pr-review.bpmn. Backs up the diagram's approval step: every tool
// that WRITES into this store makes Claude Code ask the human at the call
// (permissionDecision "ask"), even if a skill forgot the approval. Reads and every other tool pass
// untouched. CLAUDE-ONLY: hooks are a Claude Code mechanism.
//
// Reads the PreToolUse hook JSON on stdin. Prints the decision JSON on stdout and exits 0 when the
// call writes into a guarded store; prints nothing and exits 0 otherwise.

const STORES = [
  { name: 'Pull Requests im Repository', approval: 'Merge freigeben', tools: [], bash: ['gh pr merge'], file: null },
];

const input = JSON.parse(await new Response(process.stdin).text());
const tool = input.tool_name;
const command = String(input.tool_input?.command ?? '').replace(/\s+/g, ' ').trim();
const filePath = input.tool_input?.file_path;

const hit = STORES.find((s) => {
  // Matches the command anywhere in a chain and with options between the words (gh -R org/repo pr merge).
  if (tool === 'Bash') return s.bash.some((p) => new RegExp(`(^|[;&|] ?|\\s)${p.split(' ').join('\\b[^;&|]* ')}\\b`).test(command));
  if (!s.tools.includes(tool)) return false;
  return !s.file || (filePath && filePath.endsWith(s.file));
});

if (hit) {
  console.log(JSON.stringify({
    hookSpecificOutput: {
      hookEventName: 'PreToolUse',
      permissionDecision: 'ask',
      permissionDecisionReason: `Write to "${hit.name}" needs approval (step "${hit.approval}")`,
    },
  }));
}
process.exit(0);
